(372, 4, NULL, 1, 'Las condiciones físicas del lugar donde trabajo (orden, limpieza, iluminación, ventilación) son adecuadas.', 'rating_estrellas', NULL, NULL, NULL, 1, 1),
(373, 4, NULL, 2, 'Tengo las herramientas y materiales necesarios para   realizar bien mi trabajo.', 'rating_estrellas', NULL, NULL, NULL, 1, 2),
(374, 4, NULL, 3, 'Mi meta de trabajo es razonable y alcanzable.', 'rating_estrellas', NULL, NULL, NULL, 1, 3),
(375, 4, NULL, 4, 'Las instrucciones y procesos que debo seguir están   bien definidos y claros.', 'rating_estrellas', NULL, NULL, NULL, 1, 4),
(376, 4, NULL, 5, 'Recibo apoyo y guía de mi supervisor o team leader   cuando lo necesito.', 'rating_estrellas', NULL, NULL, NULL, 1, 5),
(377, 4, NULL, 6, 'Me siento valorado(a) por el trabajo que realizo.', 'rating_estrellas', NULL, NULL, NULL, 1, 6),
(378, 4, NULL, 7, 'Tengo buenas relaciones con mis compañeros de   trabajo.', 'rating_estrellas', NULL, NULL, NULL, 1, 7),
