(384, 4, NULL, 13, 'Siento que la empresa se preocupa por mi bienestar y   desarrollo.', 'rating_estrellas', NULL, NULL, NULL, 1, 13),
(385, 4, NULL, 14, 'Estoy motivado(a) para seguir trabajando en esta   empresa a largo plazo.', 'rating_estrellas', NULL, NULL, NULL, 1, 14),
(386, 4, NULL, 15, 'Estoy satisfecho(a) con los beneficios sociales que   me ofrece la organización.', 'rating_estrellas', NULL, NULL, NULL, 1, 15),
(387, 4, NULL, 16, 'Mi jefe directo me trata justamente y evita   favoritismos.', 'rating_estrellas', NULL, NULL, NULL, 1, 16),
