(401, 1, NULL, 1, '¿Con quién te puedes apoyar si tienes una duda de operación o no tienes material para inspeccionar?', 'seleccion_unica', '[\"ING. Calidad \\/ supervisor\",\"Supervisor \\/ L\\u00edder\"]', '[1]', NULL, 1, 1),
(402, 1, NULL, 2, '¿A quién aviso si tengo un accidente en planta?', 'seleccion_unica', '[\"Supervisor\",\"EHS\"]', '[0]', NULL, 1, 2),
