  `fecha_en_preparacion` datetime DEFAULT NULL,
  `fecha_listo` datetime DEFAULT NULL,
  `fecha_entrega` datetime DEFAULT NULL,
  `fecha_regreso` datetime DEFAULT NULL,
  `motivo_regreso` text DEFAULT NULL,
  `motivo_devolucion` text DEFAULT NULL COMMENT 'Motivo de devolución del EPP',
  `lentes` tinyint(1) DEFAULT 0,
  `chaleco` tinyint(1) DEFAULT 0,
  `guantes` tinyint(1) DEFAULT 0,
  `zapatos` tinyint(1) DEFAULT 0,
  `playeras` tinyint(1) DEFAULT 0,
  `tapones` tinyint(1) DEFAULT 0,
  `casco` tinyint(1) DEFAULT 0,
  `mangas_anticorte` tinyint(1) DEFAULT 0,
  `mandil` tinyint(1) DEFAULT 0,
  `items_adicionales` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Items adicionales que no están en las columnas fijas (tipo_item, cantidad, talla, color)' CHECK (json_valid(`items_adicionales`)),
  `talla_guantes_solicitada` varchar(10) DEFAULT NULL,
  `talla_zapatos_solicitada` varchar(10) DEFAULT NULL,
  `talla_playeras_solicitada` varchar(10) DEFAULT NULL,
  `talla_chaleco_solicitada` varchar(10) DEFAULT NULL,
  `color_chaleco_solicitado` varchar(20) DEFAULT NULL COMMENT 'Color del chaleco solicitado: Naranja o Verde',
  `talla_guantes_entregada` varchar(10) DEFAULT NULL,
  `talla_zapatos_entregada` varchar(10) DEFAULT NULL,
  `talla_playeras_entregada` varchar(10) DEFAULT NULL,
  `talla_chaleco_entregada` varchar(10) DEFAULT NULL,
  `color_chaleco_entregado` varchar(20) DEFAULT NULL COMMENT 'Color del chaleco entregado: Naranja o Verde',
  `comentarios_compras` text DEFAULT NULL,
  `id_usuario_solicita` int(11) NOT NULL,
  `id_usuario_prepara` int(11) DEFAULT NULL,
  `id_usuario_recibe` int(11) DEFAULT NULL,
  `confirmado_por_compras` tinyint(1) DEFAULT 0 COMMENT 'Indica si compras confirmó la entrega',
  `fecha_entrega_compras` datetime DEFAULT NULL COMMENT 'Fecha y hora en que compras confirmó la entrega',
  `id_usuario_entrega` int(11) DEFAULT NULL COMMENT 'ID del usuario de compras que confirmó la entrega',
  `confirmado_por_usuario` tinyint(1) DEFAULT 0 COMMENT 'Indica si el usuario confirmó la recepción',
  `fecha_recibido_usuario` datetime DEFAULT NULL COMMENT 'Fecha y hora en que el usuario confirmó la recepción',
  `cancelado_por_usuario` tinyint(1) DEFAULT 0 COMMENT 'Usuario solicitó cancelación (solo para estado 4)',
  `fecha_cancelacion_usuario` datetime DEFAULT NULL COMMENT 'Fecha en que usuario solicitó cancelación',
  `confirmado_cancelacion_compras` tinyint(1) DEFAULT 0 COMMENT 'Compras confirmó cancelación y recibió EPP de vuelta',
  `fecha_confirmacion_cancelacion_compras` datetime DEFAULT NULL COMMENT 'Fecha en que compras confirmó la cancelación',
  `motivo_cancelacion` text DEFAULT NULL COMMENT 'Motivo de cancelación',
  `id_usuario_cancela` int(11) DEFAULT NULL COMMENT 'ID del usuario que canceló la solicitud (puede ser usuario o compras)',
  `id_usuario_confirmo_cancelacion` int(11) DEFAULT NULL COMMENT 'ID del usuario de compras que confirmó la cancelación del usuario'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

