  `id` int(11) NOT NULL,
  `ticket_id` varchar(50) NOT NULL,
  `token` varchar(64) NOT NULL,
  `p1_comunicacion` tinyint(1) NOT NULL COMMENT 'La comunicación fue clara, amable y oportuna',
  `p2_satisfaccion` tinyint(1) NOT NULL COMMENT 'Qué tan satisfecho con el servicio recibido',
  `p3_tiempo_respuesta` tinyint(1) NOT NULL COMMENT 'El tiempo de respuesta inicial fue...',
  `p4_resolucion` tinyint(1) NOT NULL COMMENT 'Mi problema quedó resuelto completamente',
  `p5_facilidad` tinyint(1) NOT NULL COMMENT 'Me resultó fácil resolver mi solicitud con TI',
  `promedio` decimal(3,2) GENERATED ALWAYS AS ((`p1_comunicacion` + `p2_satisfaccion` + `p3_tiempo_respuesta` + `p4_resolucion` + `p5_facilidad`) / 5) STORED,
  `comentarios` text DEFAULT NULL COMMENT 'Si algo no quedó bien o podemos mejorar...',
  `es_automatica` tinyint(1) DEFAULT 0 COMMENT '1 = auto-evaluado por no responder en 24h',
  `fecha_respuesta` datetime DEFAULT current_timestamp(),
  `ip_respuesta` varchar(45) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

